import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/","title":"Apollo","lang":"en-US","frontmatter":{"home":true,"title":"Apollo","heroImage":"/logo.png","heroText":"Apollo","tagline":"高性能 MMORPG 服务器框架","actions":[{"text":"快速开始","link":"/guide/quick-start","type":"primary"},{"text":"架构概述","link":"/architecture/overview","type":"secondary"}],"features":[{"title":"🚀 高性能","details":"基于 C++20 和现代架构设计，支持百万级并发连接"},{"title":"🎮 游戏驱动","details":"专为 MMORPG 设计，内置 AOI、战斗、属性等游戏系统"},{"title":"🧩 模块化","details":"清晰的分层架构，按需组装，易于扩展和维护"},{"title":"🔄 BigWorld 兼容","details":"提供完整的 BigWorld API 兼容层，平滑迁移现有代码"},{"title":"📡 Actor 模型","details":"基于 Actor 的并发模型，安全高效的分布式通信"},{"title":"🛠️ 开发友好","details":"完善的日志、配置、生命周期管理，专注业务逻辑"}],"footer":"MIT Licensed | Copyright © 2024-present Apollo Team"},"filePathRelative":"README.md","git":{"createdTime":1773827303000,"updatedTime":1773831170000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":2,"url":"https://github.com/cuihairu"},{"name":"Claude Opus 4.6 (1M context)","username":"","email":"noreply@anthropic.com","commits":2}]}}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h2 id="简介" tabindex="-1"><a class="header-anchor" href="#简介"><span>简介</span></a></h2><p>Apollo 是一个专为 <strong>大型多人在线角色扮演游戏 (MMORPG)</strong> 设计的高性能服务器框架。它采用现代化的 <strong>C++20</strong> 标准编写，融合了多种成熟的架构模式。</p><h2 id="核心特性" tabindex="-1"><a class="header-anchor" href="#核心特性"><span>核心特性</span></a></h2><h3 id="分层模块架构" tabindex="-1"><a class="header-anchor" href="#分层模块架构"><span>分层模块架构</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────────────┐</span>
<span class="line">│                        Applications                              │</span>
<span class="line">│  gateway-server | login-server | game-server | chat-server     │</span>
<span class="line">└─────────────────────────────────────────────────────────────────┘</span>
<span class="line">                                ↓</span>
<span class="line">┌─────────────────────────────────────────────────────────────────┐</span>
<span class="line">│                    BigWorld Compatibility                        │</span>
<span class="line">└─────────────────────────────────────────────────────────────────┘</span>
<span class="line">                                ↓</span>
<span class="line">┌──────┬──────┬──────┬──────┬──────────┬──────────┬────────────┐</span>
<span class="line">│  net │ data │ game │ actor│ framework│  runtime │   core     │</span>
<span class="line">└──────┴──────┴──────┴──────┴──────────┴──────────┴────────────┘</span>
<span class="line">                                ↓</span>
<span class="line">┌─────────────────────────────────────────────────────────────────┐</span>
<span class="line">│                        Base                                      │</span>
<span class="line">│  Time | ThreadPool | IdPool | Memory | String                   │</span>
<span class="line">└─────────────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="bigworld-架构支持" tabindex="-1"><a class="header-anchor" href="#bigworld-架构支持"><span>BigWorld 架构支持</span></a></h3><ul><li><strong>CellApp</strong> - 空间分割的游戏逻辑服务器，支持水平扩展</li><li><strong>BaseApp</strong> - 专用数据库服务器，异步 IO 设计</li><li><strong>LoginApp</strong> - 登录认证服务器</li><li><strong>GatewayApp</strong> - 高性能网关，支持连接管理和消息路由</li></ul><h3 id="aoi-九宫格系统" tabindex="-1"><a class="header-anchor" href="#aoi-九宫格系统"><span>AOI 九宫格系统</span></a></h3><ul><li>O(1) 复杂度的视野查询</li><li>高效的消息去重机制</li><li>支持跨 CellApp 边界处理</li></ul><h2 id="快速开始" tabindex="-1"><a class="header-anchor" href="#快速开始"><span>快速开始</span></a></h2><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 克隆仓库</span></span>
<span class="line"><span class="token function">git</span> clone https://github.com/your-org/apollo.git</span>
<span class="line"><span class="token builtin class-name">cd</span> apollo</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 安装依赖 (使用 vcpkg)</span></span>
<span class="line"><span class="token function">vcpkg</span> <span class="token function">install</span> openssl:x64-windows protobuf:x64-windows</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 构建项目</span></span>
<span class="line">cmake <span class="token parameter variable">-B</span> build <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span><span class="token punctuation">[</span>vcpkg-root<span class="token punctuation">]</span>/scripts/buildsystems/vcpkg.cmake</span>
<span class="line">cmake <span class="token parameter variable">--build</span> build <span class="token parameter variable">--config</span> Release</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 运行游戏服务器</span></span>
<span class="line">./build/bin/game-server</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="文档导航" tabindex="-1"><a class="header-anchor" href="#文档导航"><span>文档导航</span></a></h2><table><thead><tr><th>章节</th><th>描述</th><th>链接</th></tr></thead><tbody><tr><td><strong>快速开始</strong></td><td>安装、构建、运行</td><td><a href="/guide/" target="_blank" rel="noopener noreferrer">指南</a></td></tr><tr><td><strong>架构设计</strong></td><td>BigWorld、AOI、进程架构</td><td><a href="/architecture/" target="_blank" rel="noopener noreferrer">架构</a></td></tr><tr><td><strong>模块说明</strong></td><td>各模块详细文档</td><td><a href="/modules/" target="_blank" rel="noopener noreferrer">模块</a></td></tr><tr><td><strong>服务器应用</strong></td><td>GatewayApp、LoginApp、BaseApp、CellApp</td><td><a href="/apps/" target="_blank" rel="noopener noreferrer">应用</a></td></tr><tr><td><strong>API 参考</strong></td><td>接口与类说明</td><td><a href="/api/" target="_blank" rel="noopener noreferrer">API</a></td></tr></tbody></table><h2 id="社区" tabindex="-1"><a class="header-anchor" href="#社区"><span>社区</span></a></h2><ul><li><strong>GitHub</strong>: <a href="https://github.com/your-org/apollo" target="_blank" rel="noopener noreferrer">https://github.com/your-org/apollo</a></li><li><strong>Issues</strong>: <a href="https://github.com/your-org/apollo/issues" target="_blank" rel="noopener noreferrer">https://github.com/your-org/apollo/issues</a></li><li><strong>Discussions</strong>: <a href="https://github.com/your-org/apollo/discussions" target="_blank" rel="noopener noreferrer">https://github.com/your-org/apollo/discussions</a></li></ul><h2 id="许可证" tabindex="-1"><a class="header-anchor" href="#许可证"><span>许可证</span></a></h2><p><a href="LICENSE">MIT</a> License</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};